export default function AboutPage() {
  const { t } = useI18n();
  const theme = useTheme();
  const isDark = theme.palette.mode === "dark";

  const socials = [
    {
      name: "GitHub",
      username: t.about.github,
      icon: <GitHubIcon sx={{ fontSize: 24 }} />,
      href: "https://github.com/jadrens",
      color: "#181717",
    },
    {
      name: "YouTube",
      username: t.about.youtube,
      icon: <YouTubeIcon />,
      href: "https://www.youtube.com/@LoongRens",
      color: "#FF0000",
    },
    {
      name: "Bilibili",
      username: t.about.bilibili,
      icon: <BilibiliIcon />,
      href: "https://space.bilibili.com/435996008",
      color: "#00A1D6",
    },
    {
      name: "Telegram",
      username: t.about.telegram,
      icon: <TelegramIcon />,
      href: "https://t.me/dragonrens",
      color: "#26A5E4",
    },
    {
      name: "Email",
      username: t.about.email,
      icon: <EmailIcon sx={{ fontSize: 24 }} />,
      href: `mailto:${t.about.email}`,
      color: isDark ? "#D44638" : "#B23121",
    },
  ];

  return (
    <div className="min-h-screen flex flex-col">
      <Navbar />
      <Box
        component="main"
        sx={{
          flex: 1,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          px: 3,
          py: 8,
        }}
      >
        <Box sx={{ width: "100%", maxWidth: 480 }}>
          <Box sx={{ textAlign: "center", mb: 5 }}>
            <Avatar
              src="/avatar.png"
              alt="dragonren"
              sx={{
                width: 100,
                height: 100,
                mx: "auto",
                mb: 3,
                border: 3,
                borderColor: "primary.main",
              }}
            />
            <Typography variant="h4" component="h1" sx={{ fontWeight: 700, mb: 1 }}>
              dragonren
            </Typography>
            <Typography variant="body1" color="text.secondary">
              {t.about.description}
            </Typography>
          </Box>

          <Typography
            variant="overline"
            sx={{
              display: "block",
              mb: 2,
              textAlign: "center",
              color: "text.secondary",
              fontWeight: 600,
              letterSpacing: 1.5,
            }}
          >
            {t.about.socials}
          </Typography>

          <Box sx={{ display: "flex", flexDirection: "column", gap: 1.5 }}>
            {socials.map((social) => (
              <Paper
                key={social.name}
                component={MuiLink}
                href={social.href}
                target="_blank"
                rel="noopener noreferrer"
                elevation={0}
                sx={{
                  display: "flex",
                  alignItems: "center",
                  gap: 2,
                  p: 2,
                  borderRadius: 2,
                  textDecoration: "none",
                  border: 1,
                  borderColor: "divider",
                  transition: "all 0.2s ease",
                  "&:hover": {
                    borderColor: social.color,
                    transform: "translateX(4px)",
                    bgcolor: alpha(social.color, 0.08),
                  },
                }}
              >
                <Box
                  sx={{
                    width: 48,
                    height: 48,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    borderRadius: 2,
                    bgcolor: alpha(social.color, 0.12),
                    color: social.color,
                    flexShrink: 0,
                  }}
                >
                  {social.icon}
                </Box>
                <Box sx={{ flex: 1, minWidth: 0 }}>
                  <Typography variant="subtitle2" sx={{ fontWeight: 600, color: "text.primary" }}>
                    {social.name}
                  </Typography>
                  <Typography
                    variant="body2"
                    sx={{
                      color: "text.secondary",
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      whiteSpace: "nowrap",
                    }}
                  >
                    {social.username}
                  </Typography>
                </Box>
              </Paper>
            ))}
          </Box>
        </Box>
      </Box>
      <Footer />
    </div>
  );
}